"""Checks if a chunk ended between the previous and current word.

    Args:
        prev_tag: previous chunk tag.
        tag: current chunk tag.
        prev_type: previous type.
        type_: current type.

    Returns:
        chunk_end: boolean.
    """
def end_of_chunk(prev_tag: Any, tag: Any, prev_type: Any, type_: Any) -> object {
    chunk_end = False;
    if (prev_tag == 'E') {
        chunk_end = True;
    }
    if (prev_tag == 'S') {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'B')) {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'S')) {
        chunk_end = True;
    }
    if ((prev_tag == 'B') and (tag == 'O')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'B')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'S')) {
        chunk_end = True;
    }
    if ((prev_tag == 'I') and (tag == 'O')) {
        chunk_end = True;
    }
    if ((prev_tag != 'O') and (prev_tag != '.') and (prev_type != type_)) {
        chunk_end = True;
    }
    return chunk_end;
}

"""
    Solve x = a^b % c
    :param base: a
    :param power: b
    :param mod: c
    :return: x
    """
def mod_pow(base: Any, power: Any, mod: Any) -> object {
    if (power < 0) {
        return -1;
    }
    base %= mod;
    result = 1;
    while (power > 0) {
        if (power & 1) {
            result = (result * base) % mod;
        }
        power = power >> 1;
        base = (base * base) % mod;
    }
    return result;
}
